        *alignment = 0.0;
        return ADCS_E_DEGENERATE;
    }

    d = adcs_vec3_dot(&cb_n, &cr_n);
    *alignment = ADCS_CLAMP(d, -1.0, 1.0);
    return ADCS_OK;
}

